def split_pairs(g):
    h=len(g); w=len(g[0])
    for i in range(h):
        if len(set(g[i]))==1 and g[i][0]!=0:
            return g[:i],g[i+1:]
    for j in range(w):
        if len({r[j] for r in g})==1 and g[0][j]!=0:
            return [r[:j] for r in g],[r[j+1:] for r in g]
def transform(grid):
    a,b=split_pairs(grid)
    return [[2 if x and y else 0 for x,y in zip(ra,rb)] for ra,rb in zip(a,b)]
